/// 学校列表里的一所学校
class SchoolInfo {
  const SchoolInfo({
    required this.name,
    required this.url,
    this.type = '',
    this.verified = false,
  });

  /// 学校名称，会用作课表默认名称
  final String name;

  /// 教务系统入口地址（登录页或统一身份认证页）
  final String url;

  /// 教务系统类型，如 `jwglxt`。目前只作记录：解析是挨个试的，不靠它猜
  final String type;

  /// 是否已经拿真实课表页验证过。没验证过的要如实标出来，
  /// 不能让用户以为「列表里有就一定能用」
  final bool verified;

  /// 搜索匹配：按校名做包含匹配，忽略大小写与空格
  bool matches(String keyword) {
    final query = keyword.replaceAll(RegExp(r'\s+'), '').toLowerCase();
    if (query.isEmpty) return true;
    return name.replaceAll(RegExp(r'\s+'), '').toLowerCase().contains(query);
  }
}

/// 其它学校的列表。
///
/// 这份列表**直接内置在包里，不依赖任何服务器**，因此 App 完全离线也能选学校，
/// 也不会因为某个接口挂了就用不了。
///
/// 收录分两档：
/// - 拿真实课表页验证过能用的，`verified: true`，排在最前面
/// - 从公开的课程表适配仓库整理来的教务系统入口，只保证网址来自真实提交，
///   没验证过能不能解析，一律 `verified: false`，界面上会如实标出来
///
/// 之所以敢收这么多没验证的：解析器覆盖不到的学校，用户还能走「AI 识别导入」
/// 那条路，不至于选完学校就卡死。入口给全一点，用户能少手打一串网址。
///
/// 想加学校或修正网址，请提 issue（模板见仓库 `.github/ISSUE_TEMPLATE/`）。
